mapper.select:
SELECT

FROM Account a WHERE 1 = 1 

    AND a.id= #{id}


    AND a.unid= #{unid}


    AND a.userId= #{userId}


    AND a.country= #{country}


    AND a.mobile LIKE CONCAT('%',#{mobile}, '%') 


    AND a.accountName LIKE CONCAT('%',#{accountName}, '%') 


    AND a.realName LIKE CONCAT('%',#{realName}, '%')


    AND a.cnic = #{cnic}


    AND a.email LIKE CONCAT('%',#{email}, '%') 


    AND a.gender = #{gender}


    AND a.deviceId = #{deviceId}


    AND a.city = #{city}


    AND a.invitationCode= #{invitationCode}


    AND a.referralCode= #{referralCode}


    AND a.source = #{source}


    AND a.status = #{status}

order by a.createTime desc

select
a.id as id,
a.unid as unid,
a.email as email,
a.invitationCode as invitationCode,
a.referralCode as referralCode,
a.createTime as createTime,
b.id as inviteId,
b.unid as inviteUnid,
b.email as inviteEmail
from Account a,Account b where a.referralCode = b.invitationCode  and   (a.referralCode is not null and a.referralCode != '')

    AND a.id= #{entity.id}


    AND a.unid= #{entity.unid}


    AND a.email= #{entity.email}


    AND b.id= #{entity.inviteId}


    AND b.unid= #{entity.inviteUnid}


    AND b.email= #{entity.inviteEmail}

SELECT

FROM Account a
WHERE  a.referralCode = #{referralCode}

SELECT

FROM Account a
WHERE  a.invitationCode = #{invitationCode}
